import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Security BoF - JC Lopez, IBM","description":"","frontmatter":{"title":"Ceph Security BoF - JC Lopez, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","安全性","分布式存储","Rook","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Security_BoF_-_JC_Lopez_IBM.md","filePath":"posts/2023/Ceph_Security_BoF_-_JC_Lopez_IBM.md","lastUpdated":1780459816000}'),t={name:"posts/2023/Ceph_Security_BoF_-_JC_Lopez_IBM.md"};function r(n,l,s,p,h,u){return i(),o("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li><strong>JC Lopez</strong>：IBM研发人员，长期从事Ceph和Seth相关工作。</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>Ceph安全</li><li>存储强化</li><li>Rook项目</li><li>Ceph存储系统</li></ul><h4 id="主要讨论内容" tabindex="-1">主要讨论内容 <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容&quot;">​</a></h4><ol><li><p><strong>Ceph的未来与现状</strong>：</p><ul><li>Ceph作为存储的未来，支持块存储和对象存储。</li><li>Ceph在Kubernetes和OpenShift环境中表现出高灵活性、高可用性和可扩展性。</li></ul></li><li><p><strong>Rook项目</strong>：</p><ul><li>Rook项目旨在通过操作符模型在Kubernetes环境中部署Ceph集群。</li><li>Rook已用于OpenShift Data Foundation和IBM的Fusion Data Foundation。</li></ul></li><li><p><strong>Ceph与Rook的安全性</strong>：</p><ul><li>IBM通过安全开发生命周期（SDL）进行代码审计和渗透测试。</li><li>IBM的PSIRT（产品安全事件响应团队）负责文档化所有开源材料，确保使用的库和组件的安全性。</li></ul></li><li><p><strong>加密与密钥管理</strong>：</p><ul><li>支持在OSD级别进行数据静态加密，可以使用自管理密钥或外部密钥管理系统。</li><li>支持传输层加密，包括在Messenger层和Rados Gateway的加密。</li></ul></li><li><p><strong>网络卫生与防火墙</strong>：</p><ul><li>强调防火墙的重要性，最新版本的Ceph提供了防火墙服务文件。</li><li>控制平面SSH的安全性也需要加强。</li></ul></li><li><p><strong>Rook的具体安全措施</strong>：</p><ul><li>Rook通过CRD控制部署，支持数据静态加密和传输层加密。</li><li>CSI驱动支持KMS，允许在PV级别进行加密。</li></ul></li><li><p><strong>安全最佳实践</strong>：</p><ul><li>强调suffix的重要性，不应在生产环境中禁用。</li><li>管理客户端密钥和S3用户访问密钥的安全性。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查现有安全措施，定期更新安全代码。</li><li>遵循IBM的安全标准，修复已知漏洞。</li><li>加强与IBM同事的合作，学习新的安全流程。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>会议中提到的Ceph和Rook的安全特性将通过后续文档和演示材料进行详细说明。</li><li>鼓励与会者如有安全相关问题，可随时联系JC Lopez或其他相关人员。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议结束时，JC Lopez感谢大家的参与，并表示会将所有相关材料和幻灯片分享给与会者。</li></ul>',13)])])}const c=e(t,[["render",r]]);export{d as __pageData,c as default};
